      "path": ".dsh-plugin/shared/task-executors.mjs",
      "content": "/**\n * Pluggable headless adapters for official vendor agent CLIs.\n *\n * A caller names a configured provider/model and a task. This module picks the\n * vendor adapter, detects the fixed executable, passes a credential only into\n * that process, runs in the given directory, and captures output under a\n * timeout. The API fallback stays outside this file: the caller supplies it.\n * No caller-supplied command, package, or argument list is accepted.\n *\n * Claude: https://code.claude.com/docs/en/headless\n * Codex:  https://learn.chatgpt.com/docs/non-interactive-mode\n * Gemini: https://google-gemini.github.io/gemini-cli/docs/cli/headless.html\n */\nimport { spawn } from 'node:child_process'\nimport { StringDecoder } from 'node:string_decoder'\nimport { realpath, stat } from 'node:fs/promises'\nimport { dirname, isAbsolute, join, relative, sep, win32 } from 'node:path'\nimport { toolForProvider } from './official-tool-registry.mjs'\nimport { findGlobalPackageEntries, findNodeExecutable, officialToolEntrySelection } from './official-tool-executor.mjs'\nimport { installedModuleRoots } from './vendor-mimo-grok-adapter.mjs'\nimport { CODE_FILE, npmAttestor } from './npm-attestation.mjs'\nimport { normalizeExecutionPreference } from './model-profiles.mjs'\nimport { BILLING_MODE_LABEL, billingPlan, detectQuotaExhaustion, vendorKey } from './subscription-billing.mjs'\nimport { reasoningExecutionFields, reasoningRouteForAssignment, routeForReasoningSwitch, unsupportedCliReasoning } from './reasoning-execution.mjs'\nimport { parsePackageAssignments, packageSelectionFields } from './package-assignments.mjs'\n\nexport const MAX_TASK_BYTES = 64_000\nconst MAX_ANSWER_CHARS = 48_000\nconst MAX_OUTPUT_BYTES = 2_000_000\nconst DEFAULT_TIMEOUT_MS = 10 * 60_000\nconst MAX_TIMEOUT_MS = 45 * 60_000\nconst PROBE_TIMEOUT_MS = 8_000\nconst STOP_GRACE_MS = 5_000\nconst CANCEL_GRACE_MS = 1_500\nconst IS_WINDOWS = process.platform === 'win32'\n\nconst BASE_ENV_KEYS = Object.freeze([\n  'PATH', 'Path', 'PATHEXT', 'SystemRoot', 'windir', 'ComSpec',\n  'HOME', 'USERPROFILE', 'HOMEDRIVE', 'HOMEPATH', 'APPDATA', 'LOCALAPPDATA',\n  'PROGRAMDATA', 'TEMP', 'TMP', 'TMPDIR', 'LANG', 'LC_ALL', 'TERM',\n  'HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'NO_PROXY', 'http_proxy', 'https_proxy', 'all_proxy', 'no_proxy',\n  'SSL_CERT_FILE', 'NODE_EXTRA_CA_CERTS',\n])\n\nconst READ_ONLY_INSTRUCTION = 'Read the task supplied on standard input. Answer in the task language. Do not modify files.'\nconst executionBoundaryFailure = error => ['ROUTER_CHECKPOINT_FAILED', 'ROUTER_BUDGET_CHANGED'].includes(error?.code)\nconst usageFields = ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens']\n\n/** Subscription evidence contains reported usage only, never prices or secrets. */\nfunction subscriptionReceipt(result, { provider, model, toolId = null, channel = 'harness-llm', now = Date.now } = {}) {\n  const usage = result?.usage && typeof result.usage === 'object' && !Array.isArray(result.usage)\n    ? Object.fromEntries(usageFields.filter(key => typeof result.usage[key] === 'number'\n      && Number.isFinite(result.usage[key]) && result.usage[key] >= 0).map(key => [key, result.usage[key]])) : null\n  const notStarted = result?.notStarted === true || result?.blocked === true\n  const incomplete = result?.usageIncomplete === true || !usage\n    || !['inputTokens', 'outputTokens'].every(key => Object.hasOwn(usage, key))\n    || usageFields.some(key => result?.usage?.[key] !== undefined && !Object.hasOwn(usage ?? {}, key))\n  return { provider: String(provider ?? ''), model: String(reportedCliModel(result?.actualModel ?? result?.reportedModel) ?? model ?? ''),\n    toolId, channel, usage: usage && Object.keys(usage).length ? usage : null,\n    ...(incomplete ? { usageIncomplete: true } : {}), ...(notStarted ? { notStarted: true } : {}),\n    finishedAt: typeof result?.finishedAt === 'number' && Number.isFinite(result.finishedAt)\n      && result.fin